<?php

namespace Agent\AgentBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * DirectionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class DirectionRepository extends \Doctrine\ORM\EntityRepository
{
    public function find_sce()
    {
        $qb = $this->createQueryBuilder('m')
                ->where("m.directionGle = :role  And m.etatDirection In(2,3)" )
                ->orderBy("m.etatDirection")
                ->setParameter("role",  "DG0001");
        //var_dump($role);
       // var_dump($qb->getQuery());
        return $qb->getQuery()->getResult();
    }
    
    public function find_sce1()
    {
        $qb=$this->getEntityManager()->createQueryBuilder()
                ->from('AgentBundle:Agent','a')
                ->select('a.matricule, a.nom, a.prenoms, a.nomJeuneFille')
                ->innerJoin('AgentBundle:Direction', 'm',  Join::WITH,'m.code_dc = a.code_dc')
                ->where("m.directionGle = :role  And m.etatDirection = :conseiller And a.Fonction In (:fonction)" )
                ->orderBy("m.etatDirection")
                ->setParameter("role",  "DG0001")
                ->setParameter("fonction", array(2,8))
                ->setParameter("conseiller",  "4");
               //->setMaxResults(5);
        //var_dump($role);
       // var_dump($qb->getQuery());
        return $qb->getQuery()->getResult();
    }
    
 
    public function finddirectioncentrale() {
        $qb = $this->createQueryBuilder('d')
                ->where('d.etatDirection=:etatDirection')
                ->setParameter('etatDirection', 1)
                ->orderBy('d.rang', 'ASC');
        return $qb->getQuery()->getResult();
    }

    public function findserviceratache() {
        $qb = $this->createQueryBuilder('d')
                ->where('d.etatDirection=:etatDirection')
                ->setParameter('etatDirection', 0)
                ->orderBy('d.rang', 'ASC');
        return $qb->getQuery()->getResult();
    }


    public function tserviceListe() {
        $qb = $this->getEntityManager()->createQueryBuilder()
                ->from('AgentBundle:Direction', 'd')
                ->select('d.code_dc, d.sigle')
                ->where('d.etatDirection in (:etatDirection)')
                ->setParameter('etatDirection', [0,1,2]);
        return $qb->getQuery()->getResult();
    }
    
}
